def retrieval_metrics(results, gold, k):
    hits, rec, n = 0, 0.0, 0
    for res, g in zip(results, gold):
        if not g:
            continue
        n += 1
        found = len(set(res[:k]) & g)
        hits += found > 0
        rec += found / len(g)
    return {'hit_rate': round(hits / n, 3), 'recall': round(rec / n, 3)}

