import re

def parse_verdict(text):
    m = re.search(r'score\s*:\s*(\d+)', text, re.I)
    if not m or not 1 <= int(m.group(1)) <= 5:
        raise ValueError('no valid score')
    r = re.search(r'reason\s*:\s*(.*)', text, re.I)
    return int(m.group(1)), (r.group(1).strip() if r else '')

def agreement(human, judge):
    pairs = list(zip(human, judge))
    return {'agree': round(sum(h == j for h, j in pairs) / len(pairs), 2), 'judge_too_kind': sum(j and not h for h, j in pairs), 'judge_too_harsh': sum(h and not j for h, j in pairs)}
